66	// ─── sendMessageAction ────────────────────────────────────────────────────────
67	
68	const SendMessageSchema = z.object({
69	  conversationId: z.string().uuid(),
70	  clientId: z.string().uuid(),
71	  body: z.string().min(1).max(1600),
72	  channel: z.enum(['sms', 'email']),
73	  subject: z.string().max(200).optional(),
74	})
75	
76	export async function sendMessageAction(
77	  input: z.infer<typeof SendMessageSchema>,
78	): Promise<ActionResult<{ commId: string }>> {
79	  const authUser = await getAuthenticatedUser()
80	  if (!authUser) return { ok: false, error: 'Unauthorized' }
81	
82	  const parsed = SendMessageSchema.safeParse(input)
83	  if (!parsed.success) {
84	    return { ok: false, error: parsed.error.issues[0]?.message ?? 'Invalid input' }
85	  }
86	
87	  const { conversationId, clientId, body, channel, subject } = parsed.data
88	  const { studioId } = authUser
89	
90	  try {
91	    if (channel === 'sms') {
92	      const result = await sendSmsToClient(
93	        { studioId, clientId, body },
94	        authUser.user.id,
95	      )
96	      if (!result.ok) {
97	        return { ok: false, error: result.error ?? 'Failed to send SMS' }
98	      }
99	      revalidateMessages()
100	      return { ok: true, data: { commId: result.commId ?? '' } }
101	    }
102	
103	    if (channel === 'email') {
104	      const result = await sendEmailToClient(
105	        {
106	          studioId,
107	          clientId,
108	          subject: subject ?? '(no subject)',
109	          body,
110	        },
111	        authUser.user.id,
112	      )
113	      if (!result.ok) {
114	        return { ok: false, error: result.error ?? 'Failed to send email' }
115	      }
116	      revalidateMessages()
117	      return { ok: true, data: { commId: result.commId ?? '' } }
118	    }
119	
120	    return { ok: false, error: 'Unsupported channel' }
121	  } catch (err) {
122	    logger.error({ err, conversationId }, 'sendMessageAction: unexpected error')
123	    return { ok: false, error: 'Failed to send message' }
124	  }
125	}
