// ─── Supabase mock builder ─────────────────────────────────────────────────────

type FromReturn = {
  select: (..._args: unknown[]) => unknown
  insert: (..._args: unknown[]) => unknown
  update: (..._args: unknown[]) => unknown
  delete: (..._args: unknown[]) => unknown
  eq: (..._args: unknown[]) => unknown
  single: () => unknown
}

export function buildSupabaseMock(
  tableOverrides: Record<string, Partial<FromReturn>> = {},
) {
  const noop = () => ({ data: null, error: null })
  const defaultTable: FromReturn = {
    select: () => defaultTable,
    insert: () => ({ select: () => ({ single: noop }) }),
    update: () => defaultTable,
    delete: () => ({ count: 0, error: null }),
    eq: () => defaultTable,
    single: noop,
  }

  return {
    from: (table: string) => ({
      ...defaultTable,
      ...(tableOverrides[table] ?? {}),
    }),
    rpc: (_name: string, _args?: unknown) => Promise.resolve({ data: null, error: null }),
  }
}

/**
 * Unit tests — generateSmartReplies (pure function, no DB)
 *
 * triageConversation calls DB RPC — tested via integration / E2E.
 * We test the smart-reply engine and the rule-based triage logic via generateSmartReplies.
 */

import { describe, it, expect } from 'vitest'
import { generateSmartReplies } from '@/lib/messaging/triage'
import type { SmartReplyContext, SmartReply } from '@/lib/messaging/triage'
import { mockConversation, mockMessage, mockBookingSummary } from './fixtures'

// ─── Helpers ──────────────────────────────────────────────────────────────────

const VALID_ACTION_KINDS = new Set([
  'send_template',
  'open_calendar_reschedule',
  'share_portfolio',
  'offer_slots',
  'send_aftercare_pdf',
  'request_deposit',
])

function makeCtx(
  overrides: Partial<SmartReplyContext> = {},
): SmartReplyContext {
  return {
    conversation: mockConversation({ triage_tag: null }),
    lastInboundMessage: mockMessage({ body: '' }),
    upcomingBookings: [],
    ...overrides,
  }
}

// ─── generateSmartReplies ─────────────────────────────────────────────────────

describe('generateSmartReplies', () => {
  it('returns chips where every action.kind is a known SmartReplyAction kind', async () => {
    const ctx = makeCtx({
      conversation: mockConversation({ triage_tag: 'inquiry' }),
    })
    const chips = await generateSmartReplies(ctx)
    expect(chips.length).toBeGreaterThan(0)
    for (const chip of chips) {
      expect(VALID_ACTION_KINDS.has(chip.action.kind)).toBe(true)
    }
  })

  it('never returns more than 4 chips', async () => {
    const ctx = makeCtx({
      conversation: mockConversation({ triage_tag: 'rescheduling' }),
      upcomingBookings: [
        mockBookingSummary({ id: 'b1' }),
        mockBookingSummary({ id: 'b2' }),
        mockBookingSummary({ id: 'b3' }),
      ],
    })
    const chips = await generateSmartReplies(ctx)
    expect(chips.length).toBeLessThanOrEqual(4)
  })

  it('aftercare keyword wins over triage_tag', async () => {
    const ctx = makeCtx({
      conversation: mockConversation({ triage_tag: 'inquiry' }),
      lastInboundMessage: mockMessage({ body: 'how do i do aftercare?' }),
    })
    const chips = await generateSmartReplies(ctx)
    expect(chips.some((c) => c.action.kind === 'send_aftercare_pdf')).toBe(true)
  })

  it('healing keyword triggers aftercare chips', async () => {
    const ctx = makeCtx({
      lastInboundMessage: mockMessage({ body: 'My tattoo is healing weird' }),
    })
    const chips = await generateSmartReplies(ctx)
    expect(chips.some((c) => c.action.kind === 'send_aftercare_pdf')).toBe(true)
  })

  it('deposit keyword triggers request_deposit chip', async () => {
    const ctx = makeCtx({
      lastInboundMessage: mockMessage({ body: 'Do you need a deposit?' }),
    })
    const chips = await generateSmartReplies(ctx)
    expect(chips.some((c) => c.action.kind === 'request_deposit')).toBe(true)
  })

  it('rescheduling triage_tag returns open_calendar_reschedule when upcoming booking exists', async () => {
    const booking = mockBookingSummary({ id: 'booking-upcoming' })
    const ctx = makeCtx({
      conversation: mockConversation({ triage_tag: 'rescheduling' }),
      upcomingBookings: [booking],
    })
    const chips = await generateSmartReplies(ctx)
    const reschedule = chips.find(
      (c): c is SmartReply & { action: { kind: 'open_calendar_reschedule'; bookingId: string } } =>
        c.action.kind === 'open_calendar_reschedule',
    )
    expect(reschedule).toBeDefined()
    expect(reschedule?.action.bookingId).toBe('booking-upcoming')
  })

  it('rescheduling triage_tag returns offer_slots chip', async () => {
    const ctx = makeCtx({
      conversation: mockConversation({ triage_tag: 'rescheduling' }),
      upcomingBookings: [mockBookingSummary()],
    })
    const chips = await generateSmartReplies(ctx)
    expect(chips.some((c) => c.action.kind === 'offer_slots')).toBe(true)
  })

  it('pricing triage_tag returns send_template and share_portfolio chips', async () => {
    const ctx = makeCtx({
      conversation: mockConversation({ triage_tag: 'pricing' }),
    })
    const chips = await generateSmartReplies(ctx)
    expect(chips.some((c) => c.action.kind === 'send_template')).toBe(true)
    expect(chips.some((c) => c.action.kind === 'share_portfolio')).toBe(true)
  })

  it('inquiry triage_tag returns send_template and share_portfolio chips', async () => {
    const ctx = makeCtx({
      conversation: mockConversation({ triage_tag: 'inquiry' }),
    })
    const chips = await generateSmartReplies(ctx)
    expect(chips.some((c) => c.action.kind === 'send_template')).toBe(true)
    expect(chips.some((c) => c.action.kind === 'share_portfolio')).toBe(true)
  })

  it('deposit_paid triage_tag returns booking-confirmation send_template', async () => {
    const ctx = makeCtx({
      conversation: mockConversation({ triage_tag: 'deposit_paid' }),
    })
    const chips = await generateSmartReplies(ctx)
    const tplChip = chips.find(
      (c): c is SmartReply & { action: { kind: 'send_template'; templateSlug: string } } =>
        c.action.kind === 'send_template',
    )
    expect(tplChip).toBeDefined()
    expect(tplChip?.action.templateSlug).toBe('booking-confirmation')
  })

  it('default (no tag, no keyword) returns share_portfolio chip', async () => {
    const ctx = makeCtx({
      conversation: mockConversation({ triage_tag: null }),
      lastInboundMessage: mockMessage({ body: 'just checking in' }),
    })
    const chips = await generateSmartReplies(ctx)
    expect(chips.some((c) => c.action.kind === 'share_portfolio')).toBe(true)
  })

  it('keyword matching is case-insensitive', async () => {
    const ctx = makeCtx({
      lastInboundMessage: mockMessage({ body: 'DEPOSIT please!' }),
    })
    const chips = await generateSmartReplies(ctx)
    expect(chips.some((c) => c.action.kind === 'request_deposit')).toBe(true)
  })

  it('all returned chip ids are unique', async () => {
    const ctx = makeCtx({
      conversation: mockConversation({ triage_tag: 'rescheduling' }),
      upcomingBookings: [mockBookingSummary()],
    })
    const chips = await generateSmartReplies(ctx)
    const ids = chips.map((c) => c.id)
    expect(new Set(ids).size).toBe(ids.length)
  })

  it('all returned chips have non-empty labels', async () => {
    const ctx = makeCtx({
      conversation: mockConversation({ triage_tag: 'inquiry' }),
    })
    const chips = await generateSmartReplies(ctx)
    for (const chip of chips) {
      expect(chip.label.length).toBeGreaterThan(0)
    }
  })
})

/**
