/**
 * Unit tests — seedDefaultTemplates idempotency
 */

import { describe, it, expect, vi, beforeEach } from 'vitest'

// ─── Controllable state ───────────────────────────────────────────────────────

type InsertCall = { slug: string }
const insertedSlugs: InsertCall[] = []
let duplicateSlug: string | null = null // simulates UNIQUE violation for this slug

// ─── Mocks ────────────────────────────────────────────────────────────────────

vi.mock('@/lib/supabase/server', () => ({
  createServiceRoleClient: vi.fn(() => ({
    from: (_table: string) => ({
      insert: (row: Record<string, unknown>) => ({
        select: () => ({
          single: async () => {
            const slug = row['slug'] as string
            if (slug === duplicateSlug) {
              return { data: null, error: { code: '23505', message: 'unique_violation' } }
            }
            insertedSlugs.push({ slug })
            return { data: { id: `id-${slug}` }, error: null }
          },
        }),
      }),
    }),
  })),
}))

// ─── Import after mocks ───────────────────────────────────────────────────────

const { seedDefaultTemplates, DEFAULT_TEMPLATES } = await import('@/lib/messaging/templates-seed')

// ─── Tests ────────────────────────────────────────────────────────────────────

describe('seedDefaultTemplates', () => {
  beforeEach(() => {
    insertedSlugs.length = 0
    duplicateSlug = null
  })

  it('inserts all 6 default templates on first call', async () => {
    const count = await seedDefaultTemplates('studio-1', 'user-1')
    expect(count).toBe(6)
    expect(DEFAULT_TEMPLATES).toHaveLength(6)
    expect(insertedSlugs).toHaveLength(6)
  })

  it('includes expected slugs: inquiry-reply, aftercare-guide, deposit-request, booking-confirmation, reschedule-offer, portfolio-share', async () => {
    await seedDefaultTemplates('studio-1', 'user-1')
    const slugs = insertedSlugs.map((r) => r.slug)
    expect(slugs).toContain('inquiry-reply')
    expect(slugs).toContain('aftercare-guide')
    expect(slugs).toContain('deposit-request')
    expect(slugs).toContain('booking-confirmation')
    expect(slugs).toContain('reschedule-offer')
    expect(slugs).toContain('portfolio-share')
  })

  it('idempotent: skips duplicate slug (23505) and returns reduced count', async () => {
    duplicateSlug = 'inquiry-reply'
    const count = await seedDefaultTemplates('studio-1', 'user-1')
    expect(count).toBe(5)
    expect(insertedSlugs.find((r) => r.slug === 'inquiry-reply')).toBeUndefined()
  })

  it('returns 0 when all 6 slugs already exist', async () => {
    // Make every insert fail with 23505 by overriding the mock to always return unique violation
    const { createServiceRoleClient } = await import('@/lib/supabase/server')
    const mockSr = createServiceRoleClient as ReturnType<typeof vi.fn>
    mockSr.mockImplementationOnce(() => ({
      from: () => ({
        insert: () => ({
          select: () => ({
            single: async () => ({ data: null, error: { code: '23505', message: 'unique_violation' } }),
          }),
        }),
      }),
    }))

    const count = await seedDefaultTemplates('studio-1', 'user-1')
    expect(count).toBe(0)
  })

  it('all default templates have non-empty body and slug', () => {
    for (const tpl of DEFAULT_TEMPLATES) {
      expect(tpl.slug.length).toBeGreaterThan(0)
      expect(tpl.body.length).toBeGreaterThan(0)
      expect(tpl.name.length).toBeGreaterThan(0)
    }
  })

  it('all default templates have is_default=true', () => {
    for (const tpl of DEFAULT_TEMPLATES) {
      expect(tpl.is_default).toBe(true)
    }
  })
})

