/**
 * Unit tests — Instagram webhook HMAC + subscription challenge verification.
 *
 * WhatsApp and WebChat share the same HMAC pattern. Test the IG handler fully;
 * spot-check WA/WC for the same contracts.
 */

import { describe, it, expect, vi, beforeEach } from 'vitest'
import { NextRequest } from 'next/server'
import { createHmac } from 'crypto'

// ─── Controllable state ───────────────────────────────────────────────────────

const META_APP_SECRET = 'test-meta-secret-abc123'
const META_VERIFY_TOKEN = 'test-verify-token-xyz'

let mockRateLimitSuccess = true

process.env['META_APP_SECRET'] = META_APP_SECRET
process.env['META_WEBHOOK_VERIFY_TOKEN'] = META_VERIFY_TOKEN

// ─── Mocks ────────────────────────────────────────────────────────────────────

vi.mock('@/lib/rate-limit', () => ({
  apiRatelimit: {
    limit: vi.fn(async () => ({
      success: mockRateLimitSuccess,
      limit: 100,
      remaining: 99,
      reset: Date.now() + 60000,
    })),
  },
}))

// ─── Import after mocks ───────────────────────────────────────────────────────

const { GET, POST } = await import('@/app/api/webhooks/instagram/route')

// ─── Helpers ──────────────────────────────────────────────────────────────────

function signBody(body: string, secret = META_APP_SECRET): string {
  return 'sha256=' + createHmac('sha256', secret).update(body).digest('hex')
}

function makeGetRequest(params: Record<string, string>): NextRequest {
  const url = new URL('http://localhost/api/webhooks/instagram')
  for (const [k, v] of Object.entries(params)) {
    url.searchParams.set(k, v)
  }
  return new NextRequest(url.toString(), { method: 'GET' })
}

function makePostRequest(body: string, signature: string): NextRequest {
  return new NextRequest('http://localhost/api/webhooks/instagram', {
    method: 'POST',
    headers: {
      'x-forwarded-for': '1.2.3.4',
      'x-hub-signature-256': signature,
    },
    body,
  })
}

// ─── GET — subscription challenge ────────────────────────────────────────────

describe('GET /api/webhooks/instagram — subscription challenge', () => {
  it('returns 200 with challenge when verify_token matches', async () => {
    const req = makeGetRequest({
      'hub.mode': 'subscribe',
      'hub.verify_token': META_VERIFY_TOKEN,
      'hub.challenge': 'challenge-abc',
    })
    const res = await GET(req)
    expect(res.status).toBe(200)
    const text = await res.text()
    expect(text).toBe('challenge-abc')
  })

  it('returns 403 when verify_token does not match', async () => {
    const req = makeGetRequest({
      'hub.mode': 'subscribe',
      'hub.verify_token': 'wrong-token',
      'hub.challenge': 'challenge-abc',
    })
    const res = await GET(req)
    expect(res.status).toBe(403)
  })

  it('returns 403 when hub.mode is not subscribe', async () => {
    const req = makeGetRequest({
      'hub.mode': 'unsubscribe',
      'hub.verify_token': META_VERIFY_TOKEN,
      'hub.challenge': 'challenge-abc',
    })
    const res = await GET(req)
    expect(res.status).toBe(403)
  })
})

// ─── POST — HMAC verification + rate limit ─────────────────────────────────────

describe('POST /api/webhooks/instagram — HMAC verification', () => {
  beforeEach(() => {
    mockRateLimitSuccess = true
  })

  it('returns 200 on valid HMAC signature', async () => {
    const body = JSON.stringify({ entry: [] })
    const req = makePostRequest(body, signBody(body))
    const res = await POST(req)
    expect(res.status).toBe(200)
  })

  it('returns 403 on invalid HMAC signature', async () => {
    const body = JSON.stringify({ entry: [] })
    const req = makePostRequest(body, 'sha256=badbadbadbad')
    const res = await POST(req)
    expect(res.status).toBe(403)
  })

  it('returns 403 when signature header is missing', async () => {
    const req = new NextRequest('http://localhost/api/webhooks/instagram', {
      method: 'POST',
      headers: { 'x-forwarded-for': '1.2.3.4' },
      body: '{}',
    })
    const res = await POST(req)
    expect(res.status).toBe(403)
  })

  it('returns 403 when signature uses wrong secret', async () => {
    const body = JSON.stringify({ entry: [] })
    const wrongSig = signBody(body, 'wrong-secret')
    const req = makePostRequest(body, wrongSig)
    const res = await POST(req)
    expect(res.status).toBe(403)
  })

  it('returns 429 when rate limit is exceeded', async () => {
    mockRateLimitSuccess = false
    const body = JSON.stringify({ entry: [] })
    const req = makePostRequest(body, signBody(body))
    const res = await POST(req)
    expect(res.status).toBe(429)
  })

  it('HMAC check is timing-safe (tampered body rejected)', async () => {
    const originalBody = JSON.stringify({ entry: [] })
    const tamperedBody = JSON.stringify({ entry: ['injected'] })
    // Sign original but send tampered body
    const req = makePostRequest(tamperedBody, signBody(originalBody))
    const res = await POST(req)
    expect(res.status).toBe(403)
  })
})

