 * Verifies: template CRUD, auto-reply rule CRUD, restore defaults,
 * category filter pills.
 *
 * Requires: Studio+ plan studio in DB.
 */

import { test, expect } from './fixtures'

test.describe('Settings — Messaging', () => {
  test.beforeEach(async ({ signedInPage }) => {
    await signedInPage.goto('/settings/messaging', { waitUntil: 'domcontentloaded' })
  })

  test('page renders with Templates and Auto-reply Rules sections', async ({ signedInPage }) => {
    await expect(signedInPage.getByRole('heading', { name: /templates/i })).toBeVisible()
    await expect(signedInPage.getByRole('heading', { name: /auto-reply|auto reply/i })).toBeVisible()
  })

  test('"+ New template" button opens TemplateEditorSheet', async ({ signedInPage }) => {
    await signedInPage.getByRole('button', { name: /new template/i }).click()

    const sheet = signedInPage.getByRole('dialog')
    await expect(sheet).toBeVisible({ timeout: 5_000 })

    // Sheet should have name and body inputs
    await expect(sheet.getByRole('textbox', { name: /name/i })).toBeVisible()
    await expect(sheet.getByRole('textbox', { name: /body/i })).toBeVisible()
  })

  test('creating a new template saves and appears in table', async ({ signedInPage }) => {
    await signedInPage.getByRole('button', { name: /new template/i }).click()
    const sheet = signedInPage.getByRole('dialog')
    await expect(sheet).toBeVisible({ timeout: 5_000 })

    const uniqueName = `E2E Test Template ${Date.now()}`
    await sheet.getByRole('textbox', { name: /name/i }).fill(uniqueName)
    await sheet.getByRole('textbox', { name: /body/i }).fill('Hello {{client_first_name}}! Test body.')

    // Slug field might auto-populate or need filling
    const slugInput = sheet.locator('input[name="slug"], input[placeholder*="slug"]')
    if (await slugInput.isVisible()) {
      await slugInput.fill(`e2e-test-${Date.now()}`)
    }

    await sheet.getByRole('button', { name: /save|create/i }).click()

    // Sheet should close
    await expect(sheet).not.toBeVisible({ timeout: 8_000 })

    // New template should appear in the table
    await expect(signedInPage.getByText(uniqueName)).toBeVisible({ timeout: 8_000 })
  })

  test('"Restore defaults" button seeds 6 default templates', async ({ signedInPage }) => {
    const restoreBtn = signedInPage.getByRole('button', { name: /restore defaults/i })
    await restoreBtn.click()

    // Success toast should appear
    await expect(
      signedInPage.locator('[data-sonner-toast], [role="status"]').filter({ hasText: /seeded|inserted|restored|default/i }),
    ).toBeVisible({ timeout: 8_000 })
  })

  test('category filter pills filter template table', async ({ signedInPage }) => {
    // Click a specific category pill — e.g., "Aftercare"
    const aftercarePill = signedInPage.getByRole('button', { name: /aftercare/i })
    if (await aftercarePill.isVisible()) {
      await aftercarePill.click()
      // Table should only show aftercare category rows
      // Non-aftercare templates should not appear (or table is empty)
      // Verify pill is active (aria-pressed or active class)
      await expect(aftercarePill).toHaveAttribute('aria-pressed', 'true')
    }
  })

  test('"+ Add rule" button opens RuleEditorSheet', async ({ signedInPage }) => {
    const addRuleBtn = signedInPage.getByRole('button', { name: /add rule/i })
    await addRuleBtn.click()

    const sheet = signedInPage.getByRole('dialog')
    await expect(sheet).toBeVisible({ timeout: 5_000 })

    // Trigger type select should be visible
    await expect(sheet.getByRole('combobox', { name: /trigger/i }).or(sheet.getByLabel(/trigger/i))).toBeVisible()
  })

  test('creating a new rule saves and appears in rule list', async ({ signedInPage }) => {
    await signedInPage.getByRole('button', { name: /add rule/i }).click()
    const sheet = signedInPage.getByRole('dialog')
    await expect(sheet).toBeVisible({ timeout: 5_000 })

    // Select trigger type
    const triggerSelect = sheet.getByLabel(/trigger/i).or(sheet.getByRole('combobox', { name: /trigger/i }))
    await triggerSelect.selectOption({ label: 'New inquiry' }).catch(async () => {
      await triggerSelect.click()
      await sheet.getByRole('option', { name: /new inquiry/i }).click()
    })

    // Template select
    const templateSelect = sheet.getByLabel(/template/i).or(sheet.getByRole('combobox', { name: /template/i }))
    const templateOptions = await templateSelect.locator('option').count().catch(() => 0)
    if (templateOptions > 0) {
      await templateSelect.selectOption({ index: 1 })
    }

    await sheet.getByRole('button', { name: /save|create/i }).click()
    await expect(sheet).not.toBeVisible({ timeout: 8_000 })
  })

  test('toggling a rule persists enabled/disabled state', async ({ signedInPage }) => {
    // Find a rule toggle (Switch or checkbox)
    const ruleToggle = signedInPage.getByRole('switch').first()
    if (await ruleToggle.isVisible()) {
      const wasChecked = await ruleToggle.isChecked()
      await ruleToggle.click()
      const isNowChecked = await ruleToggle.isChecked()
      expect(isNowChecked).toBe(!wasChecked)

      // Reload page and verify state persists
      await signedInPage.reload({ waitUntil: 'domcontentloaded' })
      const toggleAfterReload = signedInPage.getByRole('switch').first()
      await expect(toggleAfterReload).toBeVisible()
      expect(await toggleAfterReload.isChecked()).toBe(!wasChecked)
    }
  })

  test('/settings/messaging page has app sidebar', async ({ signedInPage }) => {
    const sidebar = signedInPage.getByRole('complementary').or(signedInPage.locator('[data-testid="sidebar"]'))
    await expect(sidebar.first()).toBeVisible()
  })
})

