/**
 * Unit tests — send-scheduled-message worker: pure business logic
 *
 * The worker module imports from workers/lib/ (relative paths) and validates
 * env vars at module load — making it incompatible with direct import in vitest/jsdom.
 * Strategy: test the pure branching logic (idempotency guard, channel routing,
 * payload validation) without importing the full worker module.
 *
 * Integration coverage (worker E2E) requires a Railway staging environment
 * with Redis + Twilio test credentials — tracked separately.
 */

import { describe, it, expect, vi, beforeEach } from 'vitest'

// ─── Pure logic extracted for unit testing ────────────────────────────────────

// Replicates isValidPayload from the worker
function isValidPayload(data: unknown): data is { commId: string; studioId: string } {
  return (
    typeof data === 'object' &&
    data !== null &&
    typeof (data as Record<string, unknown>)['commId'] === 'string' &&
    typeof (data as Record<string, unknown>)['studioId'] === 'string'
  )
}

// Replicates terminal status check
const TERMINAL_STATUSES = ['sent', 'delivered', 'failed', 'bounced'] as const
type TerminalStatus = typeof TERMINAL_STATUSES[number]

function isTerminalStatus(status: string): status is TerminalStatus {
  return TERMINAL_STATUSES.includes(status as TerminalStatus)
}

// Replicates Twilio status mapping
const STATUS_MAP: Record<string, 'queued' | 'sent' | 'delivered' | 'failed'> = {
  queued: 'queued',
  sending: 'queued',
  sent: 'sent',
  delivered: 'delivered',
  undelivered: 'failed',
  failed: 'failed',
  read: 'delivered',
}

// ─── Mock provider stubs ──────────────────────────────────────────────────────

const mockTwilioCreate = vi.fn().mockResolvedValue({ sid: 'SM_TEST_123' })
const mockResendSend = vi.fn().mockResolvedValue({ data: null, error: null })

beforeEach(() => {
  mockTwilioCreate.mockClear()
  mockResendSend.mockClear()
})

// ─── Payload validation ───────────────────────────────────────────────────────

describe('isValidPayload', () => {
  it('accepts valid payload with commId and studioId strings', () => {
    expect(isValidPayload({ commId: 'comm-1', studioId: 'studio-1' })).toBe(true)
  })

  it('rejects null', () => {
    expect(isValidPayload(null)).toBe(false)
  })

  it('rejects missing commId', () => {
    expect(isValidPayload({ studioId: 'studio-1' })).toBe(false)
  })

  it('rejects missing studioId', () => {
    expect(isValidPayload({ commId: 'comm-1' })).toBe(false)
  })

  it('rejects non-string commId', () => {
    expect(isValidPayload({ commId: 123, studioId: 'studio-1' })).toBe(false)
  })

  it('rejects empty object', () => {
    expect(isValidPayload({})).toBe(false)
  })
})

// ─── Idempotency guard ────────────────────────────────────────────────────────

describe('Terminal status guard (idempotency)', () => {
  it('sent is terminal', () => {
    expect(isTerminalStatus('sent')).toBe(true)
  })

  it('delivered is terminal', () => {
    expect(isTerminalStatus('delivered')).toBe(true)
  })

  it('failed is terminal', () => {
    expect(isTerminalStatus('failed')).toBe(true)
  })

  it('bounced is terminal', () => {
    expect(isTerminalStatus('bounced')).toBe(true)
  })

  it('queued is not terminal', () => {
    expect(isTerminalStatus('queued')).toBe(false)
  })
})

// ─── Twilio status mapping ────────────────────────────────────────────────────

describe('Twilio status mapping', () => {
  it('maps "queued" to queued', () => {
    expect(STATUS_MAP['queued']).toBe('queued')
  })

  it('maps "sending" to queued', () => {
    expect(STATUS_MAP['sending']).toBe('queued')
  })

  it('maps "sent" to sent', () => {
    expect(STATUS_MAP['sent']).toBe('sent')
  })

  it('maps "delivered" to delivered', () => {
    expect(STATUS_MAP['delivered']).toBe('delivered')
  })

  it('maps "undelivered" to failed', () => {
    expect(STATUS_MAP['undelivered']).toBe('failed')
  })

  it('maps "failed" to failed', () => {
    expect(STATUS_MAP['failed']).toBe('failed')
  })

  it('maps "read" to delivered', () => {
    expect(STATUS_MAP['read']).toBe('delivered')
  })
})

// ─── Provider dispatch stubs ──────────────────────────────────────────────────

describe('SMS provider dispatch', () => {
  it('Twilio create returns sid on success', async () => {
    const result = await mockTwilioCreate({ from: '+1555', to: '+1888', body: 'Hello' })
    expect(result.sid).toBe('SM_TEST_123')
  })

  it('Twilio create propagates errors for retry', async () => {
    mockTwilioCreate.mockRejectedValueOnce(new Error('Twilio 500'))
    await expect(mockTwilioCreate()).rejects.toThrow('Twilio 500')
  })
})

describe('Email provider dispatch', () => {
  it('Resend returns null error on success', async () => {
    const result = await mockResendSend({ from: 'a@b.com', to: 'c@d.com', subject: 'Hi', text: 'body' })
    expect(result.error).toBeNull()
  })

  it('Resend error object causes failure path', async () => {
    mockResendSend.mockResolvedValueOnce({ data: null, error: { message: 'API rejected' } })
    const result = await mockResendSend({})
    expect(result.error?.message).toBe('API rejected')
  })
})

// ─── Scheduling time guard ────────────────────────────────────────────────────

describe('Scheduled time guard', () => {
  it('past scheduled_for (>5s ago) is ready to dispatch', () => {
    const scheduledFor = new Date(Date.now() - 10_000).toISOString()
    const scheduledAt = new Date(scheduledFor).getTime()
    const tooEarly = scheduledAt > Date.now() + 5_000
    expect(tooEarly).toBe(false)
  })

  it('future scheduled_for (>5s from now) is too early', () => {
    const scheduledFor = new Date(Date.now() + 30_000).toISOString()
    const scheduledAt = new Date(scheduledFor).getTime()
    const tooEarly = scheduledAt > Date.now() + 5_000
    expect(tooEarly).toBe(true)
  })

  it('null scheduled_for skips time check (immediate dispatch)', () => {
    const scheduledFor: string | null = null
    // Worker only checks scheduled_for when it's non-null
    expect(scheduledFor).toBeNull()
  })
})

